import Link from 'next/link'
import { prisma } from '@/lib/prisma'
import { requireSuperAdmin } from '@/lib/authorization'
export const dynamic='force-dynamic'
export default async function VendorsAdmin({searchParams}:{searchParams:Promise<{q?:string}>}){await requireSuperAdmin();const {q=''}=await searchParams;const vendors=await prisma.vendor.findMany({where:q?{OR:[{name:{contains:q,mode:'insensitive'}},{category:{contains:q,mode:'insensitive'}}]}:undefined,orderBy:{createdAt:'desc'},take:100,include:{workspace:{select:{id:true,name:true}},products:{select:{id:true,name:true,active:true}}}});return <div className="mx-auto max-w-7xl"><div className="flex flex-col gap-3 sm:flex-row sm:items-end sm:justify-between"><div><h1 className="text-2xl font-semibold">Vendors</h1><p className="text-sm text-muted-foreground">Review vendor records and marketplace activity.</p></div><form className="flex gap-2"><input name="q" defaultValue={q} placeholder="Search vendors" className="h-10 rounded-lg border bg-background px-3 text-sm"/><button className="rounded-lg bg-primary px-4 text-sm font-medium text-primary-foreground">Search</button></form></div><div className="mt-6 grid gap-3 sm:grid-cols-2 xl:grid-cols-4">{['PENDING','APPROVED','SUSPENDED','REJECTED'].map(status=><div key={status} className="rounded-xl border bg-background p-4"><p className="text-xs text-muted-foreground">{status}</p><p className="mt-1 text-2xl font-semibold">{vendors.filter(v=>v.status===status).length}</p></div>)}</div><div className="mt-6 overflow-x-auto rounded-xl border bg-background"><table className="w-full text-left text-sm"><thead className="border-b bg-muted/40"><tr><th className="p-3">Vendor</th><th className="p-3">Status</th><th className="p-3">Workspace</th><th className="p-3">Products</th><th className="p-3">Created</th></tr></thead><tbody className="divide-y">{vendors.map(v=><tr key={v.id}><td className="p-3"><Link href={`/admin/vendors/${v.id}`} className="font-medium hover:underline">{v.name}</Link><div className="text-xs text-muted-foreground">{v.category} · {v.id}</div></td><td className="p-3">{v.status}</td><td className="p-3">{v.workspace.name}</td><td className="p-3">{v.products.length}</td><td className="p-3 text-muted-foreground">{v.createdAt.toLocaleDateString()}</td></tr>)}</tbody></table>{!vendors.length&&<div className="p-8 text-center text-sm text-muted-foreground">No vendors found.</div>}</div></div>}
